import React, { useEffect, useState } from "react";
import axios from "axios";

const ViewApplications = () => {
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);


  useEffect(() => {
    fetchApplications();
  }, []);

  const fetchApplications = async () => {
    try {
      const token = localStorage.getItem("token");

      if (!token) {
        alert("Please login first");
        setLoading(false);
        return;
      }

      const response = await axios.get(
        "http://127.0.0.1:8000/VJISS/view_applications",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setApplications(response.data);
    } catch (error) {
      console.error("Error fetching applications:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <p>Loading applications...</p>;

  return (
    <div className="p-6">
      <h2 className="text-2xl font-bold mb-4">My Internship Applications</h2>

      {applications.length === 0 ? (
        <p>No applications found.</p>
      ) : (
        <table className="min-w-full border">
          <thead>
            <tr>
              <th className="border p-2">ID</th>
              <th className="border p-2">Name</th>
              <th className="border p-2">Email</th>
              <th className="border p-2">Phone</th>
              <th className="border p-2">Education</th>
              <th className="border p-2">Internship</th>
              <th className="border p-2">Resume</th>
              <th className="border p-2">status</th>
              <th className="">rea</th>
            </tr>
          </thead>
          <tbody>
            {applications.map((app) => (
              <tr key={app.application_id}>
                <td className="border p-2">{app.application_id}</td>
                <td className="border p-2">
                  {app.first_name} {app.last_name}
                </td>
                <td className="border p-2">{app.email}</td>
                <td className="border p-2">{app.phone_number}</td>
                <td className="border p-2">{app.education}</td>

                {/* ✅ FIX IS HERE */}
                <td className="border p-2">
                  {app.internship_offers?.internship_name}
                </td>

                <td className="border p-2">
                  <a
                    href={app.resume}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-blue-600 underline"
                  >
                    View Resume
                  </a>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default ViewApplications;
